payload.description:
Kind-specific payload. Shape rules per kind:
- title: { text: string }
- objective: { statement: string }
- concept: { heading: string, body: string, callout?: string }
- example: { heading?: string, prose?: string, code?: string, language?: string }
- code_exercise: { prompt: string, language: string, starter_code?: string, expected_solution?: string, rubric?: string }
- multiple_choice: { question: string, options: [string], correct_index: integer (0-based, must index into options), explanation?: string }
- short_answer: { question: string, expected_answer: string, rubric?: string }
- reflection: { prompt: string }
- checkpoint: { prompt: string, scale_min?: integer, scale_max?: integer, scale_labels?: [string] }
- review_card: { concept_id: string (uuid), front: string, back: string }
